  'rerere.title': 'Recordar resoluciones de conflictos',
  'rerere.intro': 'Git puede memorizar cómo resolviste un conflicto y repetirlo la próxima vez que aparezca el mismo. Se rentabiliza en una rama de larga vida rebasada una y otra vez por la misma colisión — lo resuelves una sola vez.',
