  'replace.title': 'Reemplazar e injertar',
  'replace.intro':
    'git replace le dice a git que lea un objeto allí donde se pedía otro. No se reescribe nada y ningún sha cambia, lo que lo convierte en la forma honesta de acortar un clon: injerta un commit sin padres y todo lo anterior desaparece de cualquier recorrido, sin dejar de estar guardado ni de poder volver.',
  'replace.none': 'No hay reemplazos. Git te está mostrando exactamente lo que hay guardado.',
  'replace.disabled':
    'core.useReplaceRefs está en false aquí, así que git ignora todos los reemplazos de abajo: el historial se lee tal y como está guardado.',
