  'replace.rootOk': 'Injertar',
  'replace.shareHint':
    'Los reemplazos son referencias bajo refs/replace/, así que son locales hasta que se envían: git push origin "refs/replace/*" los comparte, y un clon que no los tenga ve el historial intacto.',
