  'attrs.title': 'Atributos de archivo',
  'attrs.intro':
    '.gitattributes es como un repositorio le enseña a git cosas sobre sus propios archivos: cuáles son binarios, cuáles deben concatenarse en vez de entrar en conflicto, cuáles se quedan fuera de un archivo comprimido, qué finales de línea usar. Viaja con el clon, así que arreglarlo aquí lo arregla para todos.',
  'attrs.none': 'Todavía no hay reglas. Los ajustes de abajo cubren los casos más habituales.',
  'attrs.localFile':
    'Este archivo vive en .git/info/: solo se aplica en esta máquina y nunca se confirma ni se comparte.',
  'attrs.add': 'Añadir regla',
  'attrs.remove': 'Eliminar',
  'attrs.removeTitle': '¿Eliminar esta regla?',
  'attrs.removeMessage': 'La regla de {pattern} se borrará del archivo. Deshacer la devuelve.',
  'attrs.preset.union': 'Changelog que nunca entra en conflicto',
  'attrs.preset.binary': 'Tratar como binario',
  'attrs.preset.nomerge': 'Nunca fusionar a tres bandas',
  'attrs.preset.exportIgnore': 'Dejar fuera de los archivos comprimidos',
  'attrs.preset.lf': 'Normalizar finales de línea',
  'attrs.preset.lfs': 'Seguir con LFS',
  'attrs.preset.linguist': 'Excluir de las estadísticas de lenguaje',
  'attrs.checkTitle': '¿Qué se aplica a una ruta?',
  'attrs.checkHint':
    'Las reglas vienen de varios archivos y gana la última coincidencia, así que leerlas es adivinar. Esto se lo pregunta a git.',
  'attrs.check': 'Comprobar',
  'attrs.checkNothing': 'No hay nada definido para esta ruta.',
  'attrs.driversTitle': 'Controladores de diff',
  'attrs.driversHint':
    'Un controlador de diff convierte un archivo ilegible en texto antes de que git lo compare, así un documento de Word o una hoja de cálculo tienen un historial que se puede leer. Word, Excel y JSON usan el conversor que GitHuttBr incluye; el resto se ofrece si está instalado y queda en gris si no.',
  'attrs.driverMissing': 'conversor no instalado',
  'attrs.needsBinary': 'Necesita {binary} en tu PATH.',
  'attrs.bundledConverter': 'Incluido con GitHuttBr: no hay nada que instalar.',
  'attrs.driverEphemeral': "apunta a una carpeta temporal de AppImage",
  'attrs.driverEphemeralHint': "Una versión AppImage de GitHuttBr configuró este conversor. Su carpeta en /tmp desaparece al cerrar la app, y cualquier otro usuario de este equipo podría poner en esa ruta un programa que tu próximo git diff ejecutaría. Elimínalo.",
  'attrs.driverStale': 'el conversor es anterior a 4.39',
  'attrs.driverStaleHint': 'Este conversor es el que las versiones hasta la 4.38 incluían con el nombre antiguo de la app. La app reapunta esos controladores a su conversor actual por sí sola; este no se pudo reapuntar: la ruta de un AppImage cambia en cada inicio, o no se pudo escribir la configuración. Los diffs de estos archivos fallan salvo que la instalación antigua siga en su sitio. Elimínalo y vuelve a añadir el controlador desde las sugerencias de abajo.',
  'attrs.driverRemove': "Eliminar",
  'attrs.bundledAppImage': "No disponible en la AppImage: el conversor de GitHuttBr solo existe mientras la app está abierta. Instala el paquete .deb para usarlo.",
  'attrs.filtersTitle': 'Filtros clean/smudge',
  'attrs.filtersHint': 'Un filtro reescribe el contenido del archivo a la entrada (clean, al preparar) y a la salida (smudge, al hacer checkout) — así funcionan git-lfs y la limpieza de claves. Uno equivocado corrompe tu árbol de trabajo sin hacer ruido, así que GitHuttBr exige una prueba en seco contra archivos reales antes de guardar nada.',
  'attrs.filterCleanPh': 'comando clean (stdin → stdout)',
  'attrs.filterSmudgePh': 'comando smudge (opcional)',
  'attrs.filterRequired': 'Obligatorio — la operación falla en lugar de dejar pasar los archivos',
  'attrs.filterDryRun': 'Prueba en seco',
  'attrs.filterDryRunFirst': 'Ejecuta primero la prueba en seco con estos valores exactos.',
  'attrs.filterSave': 'Guardar filtro',
  'attrs.filterNoMatches': 'Ningún archivo con seguimiento coincide con este patrón — no se pudo probar nada.',
  'attrs.filterMatched': 'Archivos que coinciden: {n} · probados: {m}.',
  'attrs.filterRoundtripOk': 'ida y vuelta correcta — smudge(clean(file)) reproduce el original',
  'attrs.filterRoundtripDifferent': 'la ida y vuelta difiere — un checkout no restauraría los bytes originales',
  'attrs.filterRoundtripSkipped': 'clean se ejecutó — sin comando smudge, no hay comprobación de ida y vuelta',
  'attrs.filterDangerTitle': '¿Guardar un filtro sin verificar?',
  'attrs.filterDangerMessage': 'La prueba en seco no pudo verificar "{name}": falló un comando, nada coincidió o la ida y vuelta no reproduce los bytes originales. Si está mal, cada checkout de los archivos coincidentes puede corromper tu árbol de trabajo en silencio.',
  'attrs.filterDangerConfirm': 'Guardar de todos modos',
  'attrs.filterRemoveTitle': '¿Eliminar el filtro?',
  'attrs.filterRemoveMessage': 'Esto borra filter.{name}.clean/smudge de tu configuración de git. Las reglas de .gitattributes que apuntan a él se quedan; sin required, los archivos coincidentes pasan entonces sin cambios.',
  'cmd.objects': 'Explorador de objetos',
  'objects.title': 'Explorador de objetos',
  'objects.intro': 'Todo lo que git guarda son cuatro tipos de objeto — commits, árboles, blobs, etiquetas — y referencias que apuntan a ellos. Recórrelos aquí. Nada de esta página cambia nada.',
