  'gitError.workflowScopeOAuth': 'GitHub rechazó el push: modifica el workflow {file} y este inicio de sesión no tiene el ámbito `workflow`. Con un inicio de sesión de GitHub CLI, ejecuta `gh auth refresh -h github.com -s workflow` y vuelve a enviar.',
  'gitError.workflowScopeToken': 'GitHub rechazó el push: modifica el workflow {file} y el token de acceso personal no puede editar workflows. Dale el ámbito `workflow` (token clásico) o Workflows: Read and write (fine-grained) y vuelve a enviar.',
  'gitError.fileTooLarge': 'GitHub rechaza archivos de más de 100 MB, y {file} es uno. Quítalo de los commits que se envían o gestiónalo con Git LFS.',
  'gitError.fileTooLargeAny': 'GitHub rechaza archivos de más de 100 MB, y el push incluye uno. Quítalo de los commits que se envían o gestiónalo con Git LFS.',
  'gitError.protectedBranch': 'El servidor protege esta rama y rechazó el push. Envía a una rama nueva y abre un pull request.',
  'gitError.noCredential': 'Git no tiene credenciales para {host}. Conecta una cuenta en Ajustes → Cuentas conectadas, o inicia sesión en el credential helper de git, y vuelve a intentarlo.',
  'gitError.boundProfileNoCredential': "Ninguna cuenta de {provider} está vinculada al perfil «{profile}» al que está asociado este repositorio, para {host}. Cambia a ese perfil e inicia sesión en Ajustes → Cuentas conectadas, o añade un token allí.",
  'gitError.githubNoCredentialGhMissing': 'Ninguna cuenta de GitHub está vinculada a este perfil para {host}. GitHub CLI (gh) no está instalado: añade un token de acceso personal en Ajustes → Cuentas conectadas, o instala gh, ejecuta `gh auth login` e inicia sesión allí.',
  'gitError.githubNoCredentialGhSignedOut': 'Ninguna cuenta de GitHub está vinculada a este perfil para {host}. GitHub CLI (gh) está instalado pero sin sesión: ejecuta `gh auth login` y luego inicia sesión en Ajustes → Cuentas conectadas, o añade allí un token de acceso personal.',
  'gitError.githubNoCredentialGhUnknown': 'Ninguna cuenta de GitHub está vinculada a este perfil para {host}. La comprobación de GitHub CLI (gh) tardó demasiado; puede que no haya conexión. Inicia sesión en Ajustes → Cuentas conectadas, o añade allí un token de acceso personal.',
  'gitError.githubNoCredentialGhSignedIn': 'Ninguna cuenta de GitHub está vinculada a este perfil para {host}. GitHub CLI (gh) tiene la sesión iniciada: inicia sesión en Ajustes → Cuentas conectadas para vincular esa cuenta a este perfil, o añade allí un token de acceso personal.',
  'gitError.noLinkedAccount': 'Ninguna cuenta de {provider} está vinculada a este perfil para {host}. Inicia sesión en Ajustes → Cuentas conectadas para vincular un inicio de sesión que guarde el credential helper de git, o añade allí un token.',
  'gitError.noLinkedAccountAnyHost': 'Ninguna cuenta de {provider} está vinculada a este perfil. Inicia sesión en Ajustes → Cuentas conectadas para vincular un inicio de sesión que guarde el credential helper de git, o añade allí un token.',
  'gitError.permissionDenied': 'El host rechazó la escritura: la cuenta en uso no puede escribir aquí, o su token caducó. Revisa el perfil activo, el acceso de la cuenta y el token.',
  'gitError.repoNotFound': 'El servidor dice que el repositorio no existe — o la cuenta en uso no puede verlo. Revisa la URL del remoto y el perfil activo.',
  'gitError.sshKey': 'El servidor rechazó tu clave SSH. Revisa qué clave tiene el agente en Ajustes → Seguridad y confirmaciones y que esté añadida a tu cuenta.',
  'gitError.tokenScope': 'A este token le falta el permiso {scopes}. Los permisos de un token no se pueden cambiar una vez creado: crea uno nuevo que lo incluya y pégalo aquí.',
  'gitError.tokenScopeAny': 'Este token no tiene los permisos necesarios. Los permisos de un token no se pueden cambiar una vez creado: crea uno nuevo con los permisos que indica el manual y pégalo aquí.',
  'gitError.bbsUserNotFound': 'No se encontró tu usuario en el servidor de Bitbucket Data Center, así que no se pueden pedir cambios desde aquí. Pídelos en el servidor.',
  'gitError.ghesNotSaved': 'Este GitHub Enterprise Server aún no está guardado en ningún perfil (debe usar https). Añádelo en Ajustes → Cuentas conectadas → GitHub y vuelve a intentarlo.',
  'gitError.bbsNotSaved': 'Este Bitbucket Data Center aún no está guardado en ningún perfil (debe usar https). Añádelo en Ajustes → Cuentas conectadas → Bitbucket y vuelve a intentarlo.',
